//! The README's format matrix is the one `Format` describes.
//!
//! The matrix is generated by `samyama_convert::format_matrix`. Run with
//! `UPDATE_README=1` to rewrite it after changing what a format supports.

const START: &str = "<!-- format-matrix:start -->\n";
const END: &str = "<!-- format-matrix:end -->";

#[test]
fn the_readme_format_matrix_matches_the_code() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("README.md");
    let readme = std::fs::read_to_string(&path).unwrap();
    let (head, rest) = readme
        .split_once(START)
        .expect("README has no format-matrix:start marker");
    let (_, tail) = rest
        .split_once(END)
        .expect("README has no format-matrix:end marker");
    let expected = format!(
        "{head}{START}{}{END}{tail}",
        samyama_convert::format_matrix()
    );
    if std::env::var_os("UPDATE_README").is_some() {
        std::fs::write(&path, &expected).unwrap();
        return;
    }
    assert_eq!(
        readme, expected,
        "README.md's format matrix is out of date; run `UPDATE_README=1 cargo test -p samyama-convert --test readme`"
    );
}
